insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'development-identity', 'Piaget''s theory of cognitive development', 'Piaget''s theory of cognitive development, or his genetic epistemology, is a comprehensive theory about the nature and development of human intelligence. It was originated by the Swiss developmental psychologist Jean Piaget (1896–1980). The theory deals with the nature of knowledge itself and how humans gradually come to acquire, construct, and use it. Piaget''s theory is mainly known as a developmental stage theory. In 1919, while working at the Alfred Binet Laboratory School in Paris, Piaget "was intrigued by the fact that children of different ages made different kinds of mistakes while solving problems". His experience and observations at the Alfred Binet Laboratory were the beginnings of his theory of cognitive development. He believed that children of different ages made different mistakes because of the "quality rather than quantity" of their intelligence. Piaget proposed four stages to describe the cognitive development of children: the sensorimotor stage, the preoperational stage, the concrete operational stage, and the formal operational stage. Each stage describes a specific age group. In each stage, he described how children develop their cognitive skills. For example, he believed children experience the world through action, represent things with words, think logically, and use reasoning.', 'Wikipedia: Piaget''s theory of cognitive development', 'https://en.wikipedia.org/w/index.php?title=Piaget''s_theory_of_cognitive_development&oldid=1379038101', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'development-identity' and body = 'Piaget''s theory of cognitive development, or his genetic epistemology, is a comprehensive theory about the nature and development of human intelligence. It was originated by the Swiss developmental psychologist Jean Piaget (1896–1980). The theory deals with the nature of knowledge itself and how humans gradually come to acquire, construct, and use it. Piaget''s theory is mainly known as a developmental stage theory. In 1919, while working at the Alfred Binet Laboratory School in Paris, Piaget "was intrigued by the fact that children of different ages made different kinds of mistakes while solving problems". His experience and observations at the Alfred Binet Laboratory were the beginnings of his theory of cognitive development. He believed that children of different ages made different mistakes because of the "quality rather than quantity" of their intelligence. Piaget proposed four stages to describe the cognitive development of children: the sensorimotor stage, the preoperational stage, the concrete operational stage, and the formal operational stage. Each stage describes a specific age group. In each stage, he described how children develop their cognitive skills. For example, he believed children experience the world through action, represent things with words, think logically, and use reasoning.');
